NAME = 'GerLeoNA28: Leonberger Bibel, NT (NA28)'
BOOK = 'Romans'

CHAPTERS = {
    1: {
        1: 'Paulus, ein Knecht von Christus Jesus, berufen als Apostel, ausgesondert für Gottes gute Nachricht, /',
        2: 'die er zuvor verheißen hat durch seine Propheten in den heiligen Schriften, /',
        3: '[nämlich] über seinen Sohn, der ‹menschlich gesehen› aus der Nachkommenschaft Davids stammt, /',
        4: 'den erklärten Sohn Gottes in Kraft nach dem heiligen Geist aufgrund der Auferstehung der Toten, Jesus Christus, unseren Herrn, /',
        5: 'durch den wir Gnade und apostolische Verantwortung erhalten haben zum Gehorsam des Glaubens unter allen Nationen, um seines Namens willen, /',
        6: 'unter denen auch ihr Berufene von Jesus Christus seid. /',
        7: 'An alle, die in Rom leben, die Geliebten Gottes, die berufenen Heiligen: /Gnade [sei mit] euch und Frieden von Gott, unserem Vater, und dem Herrn Jesus Christus!',
        8: 'Zunächst danke ich meinem Gott durch Jesus Christus für euch alle, weil euer Glaube in der ganzen Welt verkündet wird.',
        9: 'Gott, dem ich in meinem Geist mit der guten Nachricht seines Sohnes diene, ist nämlich mein Zeuge, wie ich unentwegt ‹an euch denke›',
        10: 'und in meinen Gebeten ständig darum bitte, dass ich es diesmal endlich irgendwie schaffen werde, mit Gottes Willen zu euch zu kommen.',
        11: 'Denn ich sehne mich danach, euch zu sehen, um euch etwas geistliche Gnadengabe weiterzugeben, damit ihr gestärkt werdet,',
        12: 'und das heißt, mit euch gemeinsam ermutigt zu werden durch den untereinander [vorhandenen] Glauben, euren und meinen.',
        13: 'Ich will euch aber nicht im Unklaren lassen, Geschwister, dass ich mir mehrfach vorgenommen habe (und bis jetzt abgehalten wurde), zu euch zu kommen, damit ich auch unter euch einige Frucht habe, wie unter den übrigen Nationen.',
        14: 'Sowohl den Griechen als auch den Barbaren, sowohl den Weisen als auch den Einfältigen bin ich verpflichtet;',
        15: 'so [besteht] meinerseits der Wunsch, auch euch in Rom die gute Nachricht zu verkünden.',
        16: 'Ich schäme mich nämlich der guten Nachricht nicht, denn sie ist eine Kraft Gottes zur Rettung für jeden, der glaubt, zunächst für den Judäer und dann für den Griechen.',
        17: 'Dadurch wird ja die Gerechtigkeit Gottes aus Glauben zum Glauben offenbart, wie geschrieben steht: „Der Gerechte aber wird aus Glauben leben.“',
        18: 'Denn der Zorn Gottes wird vom Himmel her über alle Gottlosigkeit und Ungerechtigkeit der Menschen offenbart, die die Wahrheit durch Ungerechtigkeit unterdrücken,',
        19: 'weil das, was von Gott erfahrbar [ist], unter ihnen sichtbar ist, denn Gott hat es für sie sichtbar gemacht.',
        20: 'Seit Erschaffung der Welt werden nämlich seine unsichtbaren [Eigenschaften] – sowohl seine ewige Kraft als auch seine Göttlichkeit – in den geschaffenen Dingen wahrgenommen und begriffen, sodass sie ohne Entschuldigung sind,',
        21: 'denn obwohl sie Gott kannten, haben sie ihn nicht als Gott verherrlicht oder ihm gedankt, sondern in ihren Überlegungen wurden sie abgestumpft und ihr uneinsichtiges Herz wurde verfinstert.',
        22: 'Indem sie vorgaben, weise zu sein, verdummten sie,',
        23: 'und sie tauschten die Herrlichkeit des unvergänglichen Gottes mit der bildlichen Darstellung eines vergänglichen Menschen und von Vögeln und Vierfüßern und Reptilien.',
        24: 'Darum hat Gott sie durch die Begierden ihrer Herzen an die Unreinheit ausgeliefert, ihre Körper unter sich zu entehren;',
        25: 'sie haben die Wahrheit Gottes getauscht mit der Lüge und das Geschöpf verehrt und bedient statt des Schöpfers, der ‹für immer› gepriesen ist, amen.',
        26: 'Deshalb hat Gott sie an unwerte Leidenschaften ausgeliefert, ihre Frauen haben nämlich den natürlichen Umgang in den widernatürlichen getauscht,',
        27: 'und genauso haben auch die Männer den natürlichen Umgang mit der Frau aufgegeben und sind in ihrer Lust zueinander entbrannt, sodass Männer mit Männern die Schamlosigkeit begangen und an sich selbst die Strafe erhalten haben, die wegen ihres Irrtums notwendig war.',
        28: 'Und weil sie es nicht bejahten, Gott anzuerkennen, lieferte sie Gott an einen wertlosen Verstand aus: zu tun, was nicht angemessen [ist],',
        29: 'erfüllt mit aller Ungerechtigkeit, Bosheit, Habgier, Schlechtigkeit, voller Neid, Mord, Streit, List, Boshaftigkeit, Schwätzer,',
        30: 'Verleumder, Gotthasser, Hochmütige, Hochstapler, Angeber, Erfinder schlechter [Dinge], den Eltern Ungehorsame,',
        31: 'Uneinsichtige, Unverlässliche, Gefühllose, Unbarmherzige.',
        32: 'Obwohl sie die Rechtsforderung Gottes kennen – dass diejenigen, die solche [Dinge] tun, des Todes würdig sind –, tun sie es nicht nur, sondern stimmen auch denen zu, die es tun.',
    },
    2: {
        1: 'Darum bist du unentschuldbar, oh Mensch – jeder, der richtet! Denn worin du den anderen richtest, verurteilst du dich selbst, weil du, der du richtest, dasselbe tust.',
        2: 'Wir wissen aber, dass das Gericht Gottes gemäß der Wahrheit gegen die ist, die solches tun.',
        3: 'Meinst du nun Folgendes, oh Mensch, der du richtest, die solches tun, und es [ebenfalls] tust: dass du dem Gericht Gottes entkommen wirst?',
        4: 'Oder verachtest du den Reichtum seiner Güte und Geduld und Langmut, weil du nicht weißt, dass dich die Güte Gottes zur Buße führt?',
        5: 'Aber wegen deiner Sturheit und deines unbußfertigen Herzens sammelst du dir selbst Zorn an, [der dich trifft] am Tag des Zorns und der Offenbarung des gerechten Gerichts Gottes,',
        6: 'der einem jeden nach seinen Werken vergelten wird:',
        7: 'einerseits denen, die mit der Beharrlichkeit eines guten Werks Herrlichkeit und Ehre und Unvergänglichkeit suchen, ewiges Leben;',
        8: 'andererseits denen, die aus Selbstsucht [handeln] und der Wahrheit nicht gehorsam sind, aber der Ungerechtigkeit gehorsam sind, Zorn und Wut.',
        9: 'Bedrängnis und Angst auf die Seele jedes Menschen, der das Schlechte bewirkt, eines Judäers zuerst und dann eines Griechen,',
        10: 'aber Herrlichkeit und Ehre und Frieden jedem, der das Gute bewirkt, einem Judäer zuerst und dann einem Griechen.',
        11: 'Es gibt nämlich keine Parteilichkeit bei Gott.',
        12: 'Denn alle, die ohne Gesetz gesündigt haben, werden auch ohne Gesetz umkommen, und alle, die unter dem Gesetz gesündigt haben, werden durch das Gesetz gerichtet werden.',
        13: 'Denn nicht die Hörer des Gesetzes [sind] gerecht vor Gott, sondern die Täter des Gesetzes werden gerechtfertigt werden.',
        14: 'Denn wann immer Heiden, die das Gesetz nicht haben, von Natur aus die [Dinge] des Gesetzes ausüben, dann sind sie, obwohl sie das Gesetz nicht haben, sich selbst das Gesetz.',
        15: 'Sie beweisen, dass das Werk des Gesetzes in ihre Herzen geschrieben [ist], indem ihr Gewissen es bestätigt und ihre Gedanken sich abwechselnd anklagen oder auch entschuldigen,',
        16: 'an dem Tag, wo Gott das Verborgene der Menschen durch Christus Jesus richtet, gemäß meiner guten Nachricht.',
        17: 'Aber wenn du dich Judäer nennst und dich auf das Gesetz verlässt und dich in Gott rühmst',
        18: 'und den Willen kennst und die entscheidenden [Dinge] bejahst, da du aus dem Gesetz unterrichtet wirst,',
        19: 'und du dich getraust, ein Wegführer der Blinden zu sein, ein Licht für die in Finsternis,',
        20: 'ein Erzieher der Törichten, ein Lehrer der Unmündigen, weil du die Verkörperung der Erkenntnis und der Wahrheit im Gesetz hast …',
        21: 'Der du also einen anderen lehrst, lehrst dich selbst nicht? Der du predigst, nicht zu stehlen, stiehlst?',
        22: 'Der du sagst, nicht ehezubrechen, begehst Ehebruch? Der du die Götzen verabscheust, begehst Tempelraub?',
        23: 'Der du dich im Gesetz rühmst, entehrst Gott durch die Übertretung des Gesetzes!',
        24: 'Denn „der Name Gottes wird euretwegen unter den Nationen in Verruf gebracht“, wie es geschrieben steht.',
        25: 'Denn eine Beschneidung nützt zwar, wenn du das Gesetz tust, aber wenn du ein Übertreter des Gesetzes bist, dann ist deine Beschneidung eine Unbeschnittenheit geworden.',
        26: 'Wenn also die Unbeschnittenheit die Rechtsforderungen des Gesetzes befolgt, wird nicht seine Unbeschnittenheit als Beschneidung angerechnet werden?',
        27: 'Und das von Natur aus Unbeschnittensein, das das Gesetz erfüllt, wird dich richten, der [du] trotz Buchstabe und Beschneidung ein Übertreter des Gesetzes [bist].',
        28: 'Es zählt nämlich nicht der Judäer im Sichtbaren, auch nicht die Beschneidung am Fleisch im Sichtbaren,',
        29: 'sondern der Judäer im Verborgenen und eine Beschneidung des Herzens – durch den Geist, nicht den Buchstaben. Sein Lob [stammt] nicht von Menschen, sondern von Gott.',
    },
    3: {
        1: 'Was [ist] also der Vorteil der Judäer oder was der Nutzen der Beschneidung?',
        2: 'Viel, in jeder Hinsicht. Zunächst einmal nämlich, dass ihnen die Aussprüche Gottes anvertraut wurden.',
        3: 'Was denn? Wenn einige untreu waren, sollte etwa ihre Untreue die Treue Gottes zunichtemachten?',
        4: 'Keineswegs! Es soll aber [deutlich] werden: Gott [ist] wahrhaftig, jeder Mensch hingegen ein Lügner, wie geschrieben steht: „...damit du mit deinen Worten recht behältst und siegen wirst, wenn du gerichtet wirst.“',
        5: 'Aber wenn unsere Ungerechtigkeit Gottes Gerechtigkeit erweist, was sollen wir sagen? [Ist] Gott, der den Zorn auferlegt, etwa ungerecht? (Ich spreche ‹aus menschlicher Sicht›)',
        6: 'Keineswegs! Wie sonst sollte Gott die Welt richten?',
        7: 'Aber wenn die Wahrheit Gottes durch meine Lüge zu seiner Ehre reichlicher geworden ist, warum werde ich dann noch wie ein Sünder gerichtet?',
        8: 'Und [folgt daraus] etwa, so wie wir in Verruf gebracht werden und wie einige behaupten, dass wir sagen: „Lasst uns Schlechtes tun, damit Gutes kommt?“Das Urteil über sie ist gerecht.',
        9: 'Was nun? Haben wir etwas voraus? In keinster Weise! Schließlich haben wir vorhin sowohl Judäer als auch Griechen beschuldigt, dass alle unter [dem Einfluss] der Sünde sind,',
        10: 'wie geschrieben steht: „Es ist keiner gerecht, auch nicht einer;',
        11: 'es gibt keinen, der versteht; es gibt keinen, der Gott sucht.',
        12: 'Alle sind abgewichen, zusammen sind sie untauglich; es gibt keinen, der Güte übt; es gibt nicht einmal einen einzigen!“',
        13: '„Ihre Kehle [ist] ein offenes Grab; sie betrügen mit ihren Zungen.“„Viperngift [ist] unter ihren Lippen.“',
        14: '„Ihr Mund ist voller Verwünschung und Bitterkeit.“',
        15: '„Ihre Füße [sind] schnell [dabei], Blut zu vergießen;',
        16: 'Verwüstung und Elend [sind] auf ihren Wegen,',
        17: 'und den Weg des Friedens haben sie nicht erkannt.“',
        18: '„Ehrfurcht vor Gott ist nicht vor ihren Augen.“',
        19: 'Wir wissen aber, dass alles, was das Gesetz sagt, es denen sagt, die im Gesetz [sind], damit jeder Mund gestopft wird und die ganze Welt Gott zur Rechenschaft verpflichtet wird.',
        20: 'Darum wird ‹kein Mensch› aus Werken des Gesetzes vor ihm gerechtfertigt werden, denn durch das Gesetz [entsteht] Sündenerkenntnis.',
        21: 'Tatsächlich ist die Gerechtigkeit Gottes, die vom Gesetz und den Propheten bezeugt wird, unabhängig vom Gesetz erschienen,',
        22: 'und zwar die Gerechtigkeit Gottes durch Glauben an Jesus Christus für alle, die glauben. Es besteht nämlich kein Unterschied,',
        23: 'denn alle haben gesündigt und lassen die Herrlichkeit Gottes vermissen,',
        24: 'sodass sie unverdient gerechtfertigt werden mittels seiner Gnade durch die Erlösung, die in Christus Jesus [besteht].',
        25: 'Ihn hat Gott als Wiedergutmachung bestimmt durch den Glauben an sein Blut zum Beweis seiner Gerechtigkeit aufgrund der Tilgung vorangegangener Sünden',
        26: 'mit der Nachsicht Gottes, zum Beweis seiner Gerechtigkeit in der jetzigen Zeit, dass er gerecht ist und den rechtfertigt, der aus Glauben an Jesus [lebt].',
        27: 'Wo [ist] also das Rühmen? Es wurde ausgeschlossen. Durch welches Gesetz? Der Werke? Nein, sondern durch das Gesetz des Glaubens.',
        28: 'Wir meinen nämlich, dass ein Mensch durch Glauben gerechtfertigt wird, unabhängig von Werken des Gesetzes.',
        29: 'Oder [ist] Gott allein [der Gott] der Judäer? Nicht auch der Heiden? Ja, auch der Heiden,',
        30: 'denn [es ist] ein Gott, der die Beschneidung aus Glauben und die Unbeschnittenheit durch Glauben rechtfertigen wird.',
        31: 'Machen wir also das Gesetz überflüssig durch den Glauben? Keineswegs! Sondern wir bestätigen das Gesetz.',
    },
    4: {
        1: 'Was sollen wir also sagen, hat Abraham, unser Vorfahre dem Fleisch nach, [für sich] gefunden?',
        2: 'Wenn nämlich Abraham aus Werken gerechtfertigt worden ist, dann hat er [Grund zum] Rühmen, jedoch nicht Gott gegenüber.',
        3: 'Denn was sagt die Schrift? „Da glaubte Abraham Gott, und es wurde ihm zur Gerechtigkeit angerechnet.“',
        4: 'Nun wird dem, der etwas leistet, der Lohn nicht gnädigerweise angerechnet, sondern gebührenderweise;',
        5: 'dem aber, der nichts leistet, sondern auf den vertraut, der den Gottlosen rechtfertigt, wird sein Glaube zur Gerechtigkeit angerechnet;',
        6: 'genauso wie auch David über das Glück des Menschen spricht, dem Gott Gerechtigkeit unabhängig von Werken anrechnet:',
        7: '„Beglückwünschenswert [sind] die, deren Gesetzlosigkeiten vergeben und deren Sünden bedeckt worden sind!',
        8: 'Beglückwünschenswert [ist] der Mensch, dessen Sünde der Herr gewiss nicht anrechnet.“',
        9: '[Bezieht sich] dieses Glück also auf die Beschneidung oder auch auf die Unbeschnittenheit? Schließlich sagen wir: Der Glaube wurde Abraham zur Gerechtigkeit angerechnet.',
        10: 'Wie wurde er also angerechnet? Als er in Beschneidung oder in Unbeschnittenheit war? Nicht in Beschneidung, sondern in Unbeschnittenheit!',
        11: 'Und er hat das Zeichen der Beschneidung erhalten als ein Siegel der Gerechtigkeit des Glaubens, den [er] in der Unbeschnittenheit [hatte], sodass er der Vater all derer ist, die im Zustand der Unbeschnittenheit glauben, damit auch ihnen die Gerechtigkeit angerechnet wird,',
        12: 'und der Vater der Beschneidung für diejenigen, die nicht bloß aus der Beschneidung [sind], sondern die sich auch nach den Fußstapfen des Glaubens richten, den unser Vater Abraham in Unbeschnittenheit [hatte].',
        13: 'Denn nicht durch das Gesetz [gilt] Abraham beziehungsweise seiner Nachkommenschaft die Verheißung, dass er der Erbe der Welt sei, sondern durch die Gerechtigkeit des Glaubens.',
        14: 'Wenn nämlich die aus dem Gesetz die Erben [wären], dann wäre der Glaube entleert und die Verheißung zunichtegemacht.',
        15: 'Schließlich bewirkt das Gesetz Zorn; wo aber kein Gesetz ist, da [gibt es] auch keine Übertretung.',
        16: 'Deshalb [geschieht es] aus Glauben, sodass nach Gnade [entschieden wird], damit die Verheißung der ganzen Nachkommenschaft sicher ist, nicht nur der [Nachkommenschaft] aus dem Gesetz, sondern auch der aus dem Glauben Abrahams (der unser aller Vater ist,',
        17: 'wie geschrieben steht: „Zum Vater vieler Völker habe ich dich gemacht“), vor dem Gott, dem er vertraute: der die Toten lebendig macht und der ruft, was nicht existiert, als ob es [bereits] existiert.',
        18: 'Der hat entgegen der Hoffnung auf Hoffnung hin geglaubt, sodass er der Vater vieler Nationen wurde, gemäß dem, was gesagt ist: „So soll deine Nachkommenschaft sein.“',
        19: 'Und ohne im Glauben schwach zu werden, machte er sich Gedanken über seinen eigenen, bereits abgestorbenen Körper (obwohl er etwa hundert Jahre [alt] war) und das Absterben der Mütterlichkeit Saras;',
        20: 'und an der Verheißung Gottes zweifelte er nicht ungläubig, sondern er wurde im Glauben gestärkt, da er Gott Ehre gab',
        21: 'und völlig überzeugt war, dass er fähig ist, was er versprochen hat, auch zu tun.',
        22: 'Darum wurde er ihm auch zur Gerechtigkeit angerechnet.',
        23: 'Es wurde aber nicht nur seinetwegen geschrieben, dass er ihm angerechnet wurde,',
        24: 'sondern auch unseretwegen, denen er angerechnet werden soll – denen, die an den glauben, der Jesus, unseren Herrn, von den Toten auferweckt hat.',
        25: 'Der wurde unserer Verfehlungen wegen ausgeliefert und um unserer Rechtfertigung willen auferweckt.',
    },
    5: {
        1: 'Weil wir also aus Glauben gerechtfertigt worden sind, haben wir Frieden mit Gott durch unseren Herrn Jesus Christus,',
        2: 'durch den wir im Glauben auch Zugang haben zu dieser Gnade, in der wir stehen, und wir rühmen uns aufgrund der Hoffnung auf die Herrlichkeit Gottes.',
        3: 'Aber nicht nur [das], sondern wir rühmen uns auch in den Bedrängnissen, weil wir wissen, dass die Bedrängnis Standhaftigkeit bewirkt,',
        4: 'die Standhaftigkeit wiederum Bewährung, die Bewährung wiederum Hoffnung.',
        5: 'Die Hoffnung aber enttäuscht nicht, weil die Liebe Gottes ausgegossen ist in unsere Herzen durch den heiligen Geist, der uns gegeben wurde.',
        6: 'Denn Christus ist zu einer Zeit, als wir noch schwach waren, für [uns] Gottlose gestorben.',
        7: 'Denn kaum jemand wird für einen Gerechten sterben (für den Gütigen wagt ja vielleicht sogar jemand zu sterben);',
        8: 'Gott hingegen erweist seine Liebe zu uns dadurch, dass Christus für uns starb, als wir noch Sünder waren.',
        9: 'Also werden wir umso mehr jetzt, nachdem wir durch sein Blut gerechtfertigt worden sind, durch ihn vor dem Zorn errettet werden.',
        10: 'Denn wenn wir mit Gott, obwohl wir [seine] Feinde waren, durch den Tod seines Sohnes versöhnt worden sind, dann werden wir umso mehr durch sein Leben gerettet werden, nachdem wir versöhnt worden sind!',
        11: 'Aber nicht nur [das], sondern wir rühmen uns auch in Gott durch unseren Herrn Jesus Christus, durch den wir jetzt die Versöhnung erhalten haben.',
        12: 'Deshalb: Genau wie durch einen einzigen Menschen die Sünde in die Welt gekommen ist (und durch die Sünde der Tod), so ist auch der Tod zu allen Menschen durchgedrungen, weil sie alle gesündigt haben –',
        13: 'denn bereits vor dem Gesetz gab es Sünde in der Welt, aber Sünde wird nicht angerechnet, wenn es kein Gesetz gibt.',
        14: 'Dennoch regierte der Tod von Adam bis Mose auch über diejenigen, die nicht ‹vergleichbar mit› der Übertretung Adams gesündigt hatten, der ein Abbild des Zukünftigen ist.',
        15: 'Doch [es gilt] nicht: „Wie die Verfehlung, so auch die Gnadengabe“! Denn wenn durch die Verfehlung eines einzigen [Menschen] die vielen gestorben sind, dann ist umso mehr die Gnade Gottes und das Geschenk in der Gnade des einen Menschen Jesus Christus den vielen gegenüber reich geworden.',
        16: 'Und [es gilt] nicht: „Wie durch den einen, der gesündigt hat, [entstand] das Geschenk“! Denn das Gericht [führte] zwar aus einer einzigen [Verfehlung] zur Verurteilung, aber die Gnadengabe aus vielen Verfehlungen zur Rechtfertigung.',
        17: 'Wenn nämlich durch die Verfehlung des einen der Tod durch den einen regiert hat, dann werden umso mehr diejenigen, die den Überfluss der Gnade und des Geschenks der Gerechtigkeit erhalten, im Leben regieren durch den einen: Jesus Christus.',
        18: 'Folglich [gilt]: Wie [es] also durch eine einzige Verfehlung für alle Menschen zur Verurteilung [kam], so [kommt es] auch durch eine einzige gerechte Tat für alle Menschen zur Rechtfertigung des Lebens.',
        19: 'Denn genau wie durch den Ungehorsam des einen Menschen die vielen zu Sündern gemacht worden sind, so werden auch durch den Gehorsam des einen die vielen zu Gerechten gemacht werden.',
        20: 'Das Gesetz aber ist hinzugekommen, damit die Verfehlung zunimmt; und wo die Sünde zugenommen hat, ist die Gnade überreich geworden,',
        21: 'damit so, wie die Sünde im Tod regiert hat, auch die Gnade regiert durch Gerechtigkeit zum ewigen Leben durch Jesus Christus, unseren Herrn.',
    },
    6: {
        1: 'Was sollen wir also sagen? Sollen wir in der Sünde verharren, damit die Gnade zunimmt?',
        2: 'Keineswegs! Die wir für die Sünde gestorben sind, wie könnten wir weiterhin in ihr leben?!?',
        3: 'Oder wisst ihr nicht, dass wir alle, die wir auf Christus Jesus getauft wurden, auf seinen Tod getauft wurden?',
        4: 'Wir wurden also zusammen mit ihm durch die Taufe in den Tod begraben, damit – genau wie Christus von den Toten auferweckt wurde durch die Herrlichkeit des Vaters – so auch wir ‹ein grundlegend neues Leben führen›.',
        5: 'Denn wenn wir mit der Art seines Todes identifiziert worden sind, dann werden wir es doch auch [mit der Art seiner] Auferstehung sein,',
        6: 'weil wir Folgendes wissen: dass unser alter Mensch mitgekreuzigt wurde, damit der Körper der Sünde zunichtegemacht wird [und] wir nicht länger der Sünde dienen.',
        7: 'Denn wer gestorben ist, ist freigesprochen von der Sünde.',
        8: 'Wenn wir aber zusammen mit Christus gestorben sind, dann glauben wir, dass wir auch zusammen mit ihm leben werden,',
        9: 'weil wir wissen, dass Christus nicht mehr stirbt, da er von den Toten auferweckt wurde; der Tod beherrscht ihn nicht länger.',
        10: 'Denn was er gestorben ist, ist er für die Sünde gestorben, ein für allemal; aber was er lebt, lebt er für Gott.',
        11: 'So auch ihr: Betrachtet euch selbst, [als] wärt ihr einerseits tot für die Sünde, andererseits lebendig für Gott in Christus Jesus!',
        12: 'Die Sünde soll also nicht in eurem sterblichen Körper regieren, sodass er seinen Begierden gehorcht.',
        13: 'Stellt eure Glieder auch nicht der Sünde als Werkzeuge der Ungerechtigkeit zur Verfügung, sondern stellt euch selbst Gott zur Verfügung, als Lebende von den Toten, und eure Glieder Gott als Werkzeuge der Gerechtigkeit!',
        14: 'Denn die Sünde wird euch nicht beherrschen; ihr seid nämlich nicht unter dem Gesetz, sondern unter der Gnade.',
        15: 'Was also? Sollen wir sündigen, weil wir nicht unter dem Gesetz sind, sondern unter der Gnade? Keineswegs!',
        16: 'Wisst ihr nicht, dass ihr – wem ihr euch selbst als Sklaven zum Gehorsam zur Verfügung stellt – Sklaven [dessen] seid, dem ihr gehorcht: entweder der zum Tod [führenden] Sünde oder des zur Gerechtigkeit [führenden] Gehorsams?',
        17: 'Aber Gott [sei] Dank, dass ihr [zwar] Sklaven der Sünde wart, aber von Herzen der Art von Lehre gehorcht habt, der ihr ausgesetzt gewesen seid.',
        18: 'Als ihr nun von der Sünde frei gemacht worden seid, seid ihr zu Knechten für die Gerechtigkeit geworden.',
        19: '(Ich rede in menschlicher Weise wegen der Schwachheit eures Fleisches.) Denn genau wie ihr eure Glieder dienstbereit der Unreinheit und der Gesetzlosigkeit zur Verfügung gestellt habt, [was wiederum] zur Gesetzlosigkeit [geführt hat], so stellt jetzt eure Glieder dienstbereit der Gerechtigkeit zur Verfügung, was zur Heiligung [führt].',
        20: 'Denn solange ihr Sklaven der Sünde wart, wart ihr der Gerechtigkeit gegenüber frei.',
        21: 'Welche Frucht hattet ihr denn damals? [Dinge], für die ihr euch jetzt schämt, denn deren Resultat [ist] der Tod.',
        22: 'Jetzt aber, nachdem ihr von der Sünde befreit und zu Knechten für Gott geworden worden seid, habt ihr eure Frucht zur Heiligung, das Resultat aber [ist] ewiges Leben.',
        23: 'Denn das Resultat der Sünde [ist] der Tod, aber die Gnadengabe Gottes [ist] ewiges Leben in Christus Jesus, unserem Herrn.',
    },
    7: {
        1: 'Oder wisst ihr nicht, Geschwister (schließlich spreche ich zu denen, die das Gesetz kennen), dass das Gesetz den Menschen beherrscht, solange er lebt?',
        2: 'Denn die verheiratete Frau ist per Gesetz an den lebenden Ehemann gebunden, aber wenn der Ehemann stirbt, ist sie vom Gesetz des Ehemannes entbunden.',
        3: 'Folglich wird sie also, während der Ehemann lebt, als Ehebrecherin bezeichnet werden, wenn sie einem anderen Mann gehört; aber wenn der Ehemann stirbt, ist sie frei von dem Gesetz, sodass sie keine Ehebrecherin ist, obwohl sie einem anderen Mann gehört.',
        4: 'Somit seid auch ihr, meine Geschwister, dem Gesetz gegenüber gestorben durch den Leib des Christus, damit ihr einem anderen gehört: demjenigen, der von den Toten auferweckt wurde, damit wir Gott Frucht bringen.',
        5: 'Denn als wir im Fleisch waren, wirkten die sündhaften Leidenschaften, die durch das Gesetz [benannt sind], in unseren Gliedern, um dem Tod Frucht zu bringen;',
        6: 'jetzt aber sind wir vom Gesetz entbunden worden, denn wir sind dem gestorben, wodurch wir gebunden waren, sodass wir in der Neuheit des Geistes dienen und nicht in der Vergangenheit des Buchstabens.',
        7: 'Was sollen wir also sagen? Das Gesetz [sei] Sünde? Keineswegs! Ich kannte doch die Sünde nicht außer durch das Gesetz; schließlich hätte ich auch die Begierde nicht gekannt, wenn nicht das Gesetz sagen würde: „Du sollst nicht begehren!“',
        8: 'Aber die Sünde nahm die Gelegenheit durch das Gebot wahr und verursachte jegliche Begierde in mir; denn ohne das Gesetz [ist] die Sünde tot.',
        9: 'Ich aber lebte früher ohne Gesetz, aber als das Gebot kam, lebte die Sünde auf.',
        10: 'Ich aber bin gestorben, und das Gebot, das zum Leben [führen sollte], das stellte sich für mich [als] zum Tod [führend] heraus.',
        11: 'Denn die Sünde nahm die Gelegenheit wahr und täuschte mich durch das Gebot, und sie tötete mich dadurch.',
        12: 'Darum [ist] das Gesetz heilig, und das Gebot heilig und gerecht und gut.',
        13: 'Ist also das Gute für mich zum Tod geworden? Keineswegs! Sondern die Sünde, damit sie als Sünde erkennbar wird, indem sie durch das Gute den Tod für mich bewirkt, sodass die Sünde durch das Gebot überaus sündig wird.',
        14: 'Wir wissen nämlich, dass das Gesetz geistlich ist, ich hingegen bin fleischlich, unter die Sünde verkauft.',
        15: 'Denn was ich vollbringe, verstehe ich nicht! Denn was ich will, das tue ich nicht, doch was ich hasse, das tue ich.',
        16: 'Und wenn ich das tue, was ich nicht will, dann stimme ich dem Gesetz zu, dass [es] gut [ist].',
        17: 'Jetzt aber vollbringe nicht mehr ich es, sondern die in mir wohnende Sünde.',
        18: 'Denn ich weiß, dass in mir – das heißt: in meinem Fleisch – nichts Gutes wohnt; denn das Gute zu wollen, liegt mir nahe, aber es zu vollbringen, nicht.',
        19: 'Denn nicht das Gute, das ich will, tue ich, sondern das Schlechte, das ich nicht will, das tue ich.',
        20: 'Aber wenn ich das tue, was ich nicht will, dann vollbringe nicht mehr ich es, sondern die in mir wohnende Sünde.',
        21: 'Folglich entdecke ich die Gesetzmäßigkeit, dass mir, der ich das Gute tun will, das Schlechte naheliegt;',
        22: 'dem inneren Menschen nach habe ich nämlich Gefallen an dem Gesetz Gottes,',
        23: 'aber ich sehe ein anderes Gesetz in meinen Gliedern, das gegen das Gesetz meines Verstandes kämpft und mich in dem Gesetz der Sünde gefangen nimmt, das in meinen Gliedern ist.',
        24: 'Ich elender Mensch! Wer wird mich von diesem Körper des Todes retten?',
        25: 'Dank aber [sei] Gott durch Jesus Christus, unseren Herrn! Folglich diene zwar ich selbst nun mit dem Verstand dem Gesetz Gottes, mit dem Fleisch aber dem Gesetz der Sünde.',
    },
    8: {
        1: 'Folglich [gibt es] jetzt keine Verurteilung [mehr] für diejenigen, die in Christus Jesus [sind].',
        2: 'Denn das Gesetz des Geistes des Lebens hat dich in Christus Jesus freigemacht vom Gesetz der Sünde und des Todes.',
        3: 'Denn ‹was dem Gesetz unmöglich war›, weil es durch das Fleisch [zu] schwach war, [ist geschehen]: Als Gott seinen eigenen Sohn in Gestalt des sündhaften Fleisches und für die Sünde schickte, verurteilte er die Sünde im Fleisch,',
        4: 'damit die rechtmäßige Forderung des Gesetzes in uns erfüllt wird, die wir nicht nach dem Fleisch leben, sondern nach dem Geist.',
        5: 'Denn die nach dem Fleisch sind, bedenken die [Dinge] des Fleisches; die aber nach dem Geist [sind], die des Geistes.',
        6: 'Die Denkweise des Fleisches [ist] nämlich der Tod, die Denkweise des Geistes aber [ist] Leben und Frieden;',
        7: 'darum [bedeutet] die Denkweise des Fleisches Feindschaft gegen Gott, schließlich lässt sie sich nicht dem Gesetz Gottes unterordnen, denn [dazu] ist sie auch nicht fähig.',
        8: 'Und die im Fleisch sind, können Gott nicht gefallen.',
        9: 'Ihr hingegen seid nicht im Fleisch, sondern im Geist, wenn wirklich Gottes Geist in euch wohnt. Und wenn jemand den Geist Christi nicht hat, dann ‹gehört dieser nicht ihm›.',
        10: 'Wenn aber Christus in euch [ist], dann [ist] zwar der Körper tot aufgrund der Sünde, aber der Geist [ist] Leben aufgrund der Gerechtigkeit.',
        11: 'Und wenn der Geist dessen, der Jesus von den Toten auferweckt hat, in euch wohnt, dann wird derjenige, der Christus auferweckt hat von den Toten, auch eure sterblichen Körper lebendig machen durch seinen Geist, der in euch wohnt.',
        12: 'Folglich, Geschwister, sind wir nun dem Fleisch gegenüber nicht verpflichtet, nach dem Fleisch zu leben.',
        13: 'Denn wenn ihr nach dem Fleisch lebt, dann werdet ihr sterben; aber wenn ihr durch den Geist die Taten des Körpers abtötet, dann werdet ihr leben.',
        14: 'Denn alle, die durch den Geist Gottes geleitet werden, die sind Söhne Gottes.',
        15: 'Denn ihr habt keinen Geist der Knechtschaft empfangen, erneut zur Furcht, sondern ihr habt einen Geist der Kindschaft empfangen, durch den wir rufen: „Abba, Vater!“',
        16: 'Der Geist selbst bestätigt unserem Geist, dass wir Kinder Gottes sind.',
        17: 'Und wenn [wir] Kinder [sind], dann auch Erben: einerseits Erben Gottes, andererseits Miterben Christi, wenn wir wirklich mitleiden, sodass wir auch mitverherrlicht werden.',
        18: 'Ich meine nämlich, dass die Leiden der jetzigen Zeit nicht [der Rede] wert [sind] gegenüber der Herrlichkeit, die im Begriff steht, uns offenbart zu werden.',
        19: 'Denn die sehnsüchtige Erwartung der Schöpfung erwartet die Offenbarung der Kinder Gottes,',
        20: 'weil die Schöpfung der Nichtigkeit unterworfen wurde – nicht freiwillig, sondern um dessentwillen, der sie unterworfen hat – auf die Hoffnung hin,',
        21: 'dass auch die Schöpfung selbst von der Knechtschaft der Vergänglichkeit befreit werden wird zur Freiheit der Herrlichkeit der Kinder Gottes.',
        22: 'Denn wir wissen, dass die ganze Schöpfung bis jetzt mitseufzt und mitleidet;',
        23: 'und nicht nur [sie], sondern auch wir selbst, die wir die Erstlingsfrucht des Geistes haben … auch wir selbst seufzen in uns selbst, während wir die Kindschaft erwarten, die Erlösung unseres Körpers.',
        24: 'Denn auf die Hoffnung hin sind wir errettet worden. Aber Hoffnung, die man sieht, ist keine Hoffnung! Denn wer erhofft, was er sieht?',
        25: 'Aber wenn wir erhoffen, was wir nicht sehen, dann erwarten wir es mit Geduld.',
        26: 'Genauso nimmt sich nun auch der Geist unserer Schwachheit an, denn wir wissen nicht, wie wir ‹in geeigneter Weise› beten sollen, doch der Geist selbst leistet Fürbitte [für uns] mit unaussprechlichen Seufzern.',
        27: 'Und der die Herzen erforscht, weiß, was die Denkweise des Geistes [ist], weil er für die Heiligen eintritt, ‹wie es Gott gefällt›.',
        28: 'Wir wissen aber, dass denen, die Gott lieben, alle [Dinge] zum Guten zusammenwirken – denen, die nach der Vorsehung berufen sind –,',
        29: 'weil er die, die er zuvor erkannt hat, auch vorherbestimmt hat, dem Ebenbild seines Sohnes gleichgestaltet [zu sein], damit er der Erstgeborene ist unter vielen Geschwistern.',
        30: 'Aber die er vorherbestimmt hat, die hat er auch berufen; und die er berufen hat, die hat er auch gerechtfertigt; und die er gerechtfertigt hat, die hat er auch verherrlicht.',
        31: 'Was sollen wir nun dazu sagen? Wenn Gott für uns [ist], wer [ist] gegen uns?',
        32: 'Der sogar [seinen] eigenen Sohn nicht verschont hat, sondern ihn für uns alle hingegeben hat … wie sollte er uns – zusammen mit ihm – nicht auch alles [andere] schenken?',
        33: 'Wer wird gegen die Erwählten Gottes Anklage erheben? Gott [ist es], der rechtfertigt!',
        34: 'Wer [ist es], der verurteilt? Christus Jesus [ist] der Gestorbene, vielmehr aber der Auferweckte, der auch zur Rechten Gottes ist [und] der auch für uns eintritt.',
        35: 'Was soll uns trennen von der Liebe Christi? Bedrängnis oder Angst oder Verfolgung oder Hunger oder Blöße oder Gefahr oder Schwert?',
        36: 'Wie geschrieben steht: „Deinetwegen werden wir den ganzen Tag getötet, / wir sind als Schlachtschafe betrachtet worden.“',
        37: 'Aber in allen diesen [Dingen] überwinden wir durch den, der uns geliebt hat.',
        38: 'Ich bin nämlich überzeugt, dass weder Tod noch Leben, weder Engel noch Gewalten, weder Gegenwärtiges noch Zukünftiges, noch Mächte,',
        39: 'weder Höhe noch Tiefe, noch irgendein anderes Geschöpf uns wird trennen können von der Liebe Gottes, die in Christus Jesus [besteht], unserem Herrn.',
    },
    9: {
        1: 'Ich sage die Wahrheit in Christus – ich lüge nicht, das bestätigt mir mein Gewissen durch den heiligen Geist –,',
        2: 'dass ich großen Kummer und unendlichen Schmerz in meinem Herzen empfinde.',
        3: 'Denn ich wünschte, ich selbst würde von Christus verflucht sein für meine Geschwister, meine Verwandten dem Fleisch nach,',
        4: 'welche Israeliten sind, denen die Kindschaft und die Herrlichkeit und die Bündnisse und die Gesetzgebung und der Gottesdienst und die Verheißungen [gelten];',
        5: 'zu ihnen [gehören] die Vorfahren und von ihnen [stammt] (‹menschlich gesehen›) der Gesalbte, der Gott über allem ist, ‹für immer› gepriesen! Amen.',
        6: '[Es ist] aber nicht so, dass das Wort Gottes hinfällig geworden ist. Denn nicht alle, die von Israel [abstammen], die [sind] Israel!',
        7: 'Auch nicht, dass sie als Abrahams Nachkommenschaft alle Kinder sind, sondern: „Durch Isaak wird dir eine Nachkommenschaft benannt werden.“',
        8: 'Das heißt: Nicht die Kinder des Fleisches [sind] diese Kinder Gottes, sondern [nur] die Kinder der Verheißung werden zur Nachkommenschaft gerechnet.',
        9: 'Folgendes [ist] nämlich die Aussage der Verheißung: „Zu dieser Zeit werde ich kommen, und Sara wird einen Sohn haben.“',
        10: 'Aber nicht nur [sie], sondern auch Rebekka, als sie von einem ‹schwanger war›, unserem Vater Isaak;',
        11: 'denn obwohl [sie] noch nicht geboren waren und weder etwas Gutes noch Schlechtes getan hatten – damit das der Erwählung entsprechende Vorhaben Gottes bleibt,',
        12: 'nicht aus Werken, sondern aus dem, der beruft –, wurde zu ihr gesagt: „Der Ältere wird dem Jüngeren dienen“,',
        13: 'wie geschrieben steht: „Jakob habe ich geliebt, Esau aber habe ich gehasst.“',
        14: 'Was sollen wir also sagen? [Besteht] etwa Ungerechtigkeit bei Gott? Keineswegs!',
        15: 'Denn zu Mose sagt er: „Ich werde verschonen, wen auch immer ich verschone, und ich werde barmherzig sein, wem auch immer ich barmherzig bin.“',
        16: 'Folglich [hängt es] also nicht an dem, der will, noch an dem, der läuft, sondern an Gott, der verschont.',
        17: 'Denn die Schrift sagt zu Pharao: „Zu eben diesem [Zweck] habe ich dich erweckt, damit ich meine Kraft an dir erweise und damit mein Name auf der ganzen Erde verkündet wird.“',
        18: 'Folglich verschont er also, wen er will, und verhärtet er, wen er will.',
        19: 'Du wirst mir nun sagen: „Warum tadelt er dann noch? Wer hat denn seinem Willen widerstanden?“',
        20: 'Oh Mensch, im Gegenteil: Wer bist du, der du Gott widersprichst? Wird etwa das Gebilde zu dem Bildenden sagen: „Warum hast du mich so gemacht?“',
        21: 'Oder hat nicht der Töpfer Vollmacht über den Ton, um aus demselben Klumpen das eine Gefäß zur Ehre, das andere zur Unehre zu machen?',
        22: 'Aber wenn Gott, obwohl er [seinen] Zorn erweisen und seine Kraft bekannt machen will, mit großer Geduld die Gefäße des Zorns ertragen hat, die zum Verderben vorbereitet sind,',
        23: 'und zwar um den Reichtum seiner Herrlichkeit über Gefäße des Erbarmens bekannt zu machen, die er zuvor zur Herrlichkeit vorbereitet hat …',
        24: 'uns, die er auch gerufen hat, nicht nur von den Judäern, sondern auch von den Heiden,',
        25: 'wie es auch in Hosea heißt: „Ich werde den, der nicht mein Volk [ist], ‚Mein Volk‘nennen, und diejenige, die nicht geliebt ist, ‚Geliebte‘.“',
        26: '„Und es wird sein an dem Ort, wo zu ihnen gesagt wurde: ‚Ihr [seid] nicht mein Volk‘, dort werden sie ‚Söhne des lebendigen Gottes‘genannt werden.“',
        27: 'Und Jesaja ruft hinsichtlich Israel: „Wenn die Zahl der Söhne Israels wie der Sand des Meeres wäre, wird [doch nur] der Rest gerettet werden;',
        28: 'denn indem er [seine] Abrechnung vollendet und abkürzt, wird der Herr sie auf der Erde durchführen.“',
        29: 'Und wie Jesaja zuvor gesagt hat: „Wenn der Herr Zebaot uns keine Nachkommenschaft übriggelassen hätte, dann wären wir wie Sodom geworden und wären Gomorra gleich geworden.“',
        30: 'Was sollen wir also sagen? Dass die Heiden, die nicht nach Gerechtigkeit streben, Gerechtigkeit erlangt haben, eine Gerechtigkeit aber, die aus Glauben [ist].',
        31: 'Israel hingegen, das nach dem Gesetz der Gerechtigkeit strebt, ist nicht zum Gesetz gelangt.',
        32: 'Weshalb? Weil [es] nicht aus Glauben [geschah], sondern wie aus Werken! Sie haben sich an dem Stein des Anstoßes gestoßen,',
        33: 'wie geschrieben steht: „Siehe!, ich lege in Zion einen Stein des Anstoßes und einen Fels des Ärgernisses, und wer auf ihn vertraut, wird nicht enttäuscht werden.“',
    },
    10: {
        1: 'Geschwister, der Wunsch meines Herzens und [mein] Flehen zu Gott für sie [betrifft] [ihre] Rettung.',
        2: 'Denn ich bezeuge ihnen, dass sie Eifer für Gott haben, aber nicht gemäß der [richtigen] Erkenntnis;',
        3: 'indem sie nämlich die Gerechtigkeit Gottes ignorieren und die eigene Gerechtigkeit zu errichten versuchen, ordnen sie sich nicht der Gerechtigkeit Gottes unter.',
        4: 'Denn das Ziel des Gesetzes [ist] Christus, zur Gerechtigkeit für jeden, der glaubt.',
        5: 'Denn Mose schreibt über die Gerechtigkeit, die aus dem Gesetz [stammt], dass der Mensch, der dies tut, durch sie leben wird.',
        6: 'Die Gerechtigkeit aus Glauben aber spricht folgendermaßen: „Sage nicht in deinem Herzen: Wer wird in den Himmel hinaufsteigen?“, das heißt, Christus herabführen;',
        7: 'oder: „Wer wird in den Abgrund hinabsteigen?“, das heißt, Christus von den Toten heraufführen.',
        8: 'Doch was sagt sie? „Das Wort ist dir nahe, in deinem Mund und in deinem Herzen.“Das ist das Wort des Glaubens, das wir predigen:',
        9: 'Wenn du mit deinem Mund Jesus als Herrn bekennst und in deinem Herzen glaubst, dass Gott ihn von den Toten auferweckt hat, dann wirst du gerettet werden.',
        10: 'Denn mit dem Herzen vertraut man zur Gerechtigkeit, und mit dem Mund bekennt man zur Rettung.',
        11: 'Denn die Schrift sagt: „Jeder, der an ihn glaubt, wird nicht enttäuscht werden.“',
        12: 'Es gibt nämlich keinen Unterschied zwischen Judäer und Grieche, denn derselbe [ist] Herr von allen und ist reich zu allen, die ihn anrufen.',
        13: 'Denn „jeder, der den Namen des Herrn anruft, wird gerettet werden“.',
        14: 'Wie sollen sie also den anrufen, an den sie nicht geglaubt haben? Und wie sollen sie an den glauben, von dem sie nicht gehört haben? Und wie sollen sie hören ohne einen, der predigt?',
        15: 'Und wie sollen sie predigen, wenn sie nicht gesandt sind? Wie geschrieben steht: „Wie willkommen [sind] die Füße derer, die Gutes verkünden.“',
        16: 'Aber nicht alle haben der guten Nachricht gehorcht. Denn Jesaja sagt: „Herr, wer hat unserer Botschaft geglaubt?“',
        17: 'Folglich [entsteht] der Glaube aus dem Hören, das Hören wiederum durch das Wort Christi.',
        18: 'Doch ich sage: Haben sie etwa nicht zugehört? Im Gegenteil. „In die ganze Welt ist ihr Schall ausgegangen und zu den Grenzen des Erdkreises ihre Worte.“',
        19: 'Doch ich sage: Hat Israel es etwa nicht erkannt? Zunächst sagt Mose: „Ich will euch auf ein ‚Nicht-Volk‘eifersüchtig machen, auf ein uneinsichtiges Volk werde ich euch zornig machen.“',
        20: 'Jesaja wiederum wagt es und sagt: „Ich wurde gefunden unter denen, die mich nicht gesucht haben, ich bin denen sichtbar geworden, die nicht nach mir gefragt haben.“',
        21: 'Zu Israel aber sagt er: „Den ganzen Tag habe ich meine Hände ausgestreckt zu einem Volk, das ungehorsam ist und Widerrede gibt.“',
    },
    11: {
        1: 'Ich sage also: Hat Gott etwa sein Volk verstoßen? Keineswegs! Denn auch ich bin ein Israelit, aus der Nachkommenschaft Abrahams, dem Stamm Benjamin.',
        2: 'Gott hat sein Volk, das er zuvor erkannt hat, nicht verstoßen. Oder wisst ihr nicht, was die Schrift durch Elija sagt, als er Gott gegen Israel vertritt:',
        3: '„Herr, sie haben deine Propheten getötet, deine Altäre abgerissen, und ich allein bin übrig geblieben, und sie trachten nach meinem Leben.“',
        4: 'Doch was sagt ihm die göttliche Antwort? „Ich habe mir 7.000 Männer übrig behalten, die [ihr] Knie dem Baal nicht gebeugt haben.“',
        5: 'So ist also auch in der jetzigen Zeit ein Rest vorhanden aufgrund gnädiger Erwählung.',
        6: 'Wenn aber durch Gnade, dann nicht länger aus Werken, sonst ist die Gnade nicht mehr Gnade.',
        7: 'Was dann? Was Israel sucht, das hat es nicht erlangt, die Erwählung aber hat es erlangt, die übrigen hingen wurden verhärtet,',
        8: 'wie geschrieben steht: „Gott hat ihnen einen Geist der Schläfrigkeit gegeben: Augen, um nicht zu sehen, und Ohren, um nicht zu hören, bis zum heutigen Tag.“',
        9: 'Und David sagt: „Ihr Tisch werde zu einer Schlinge und zu einer Falle und zu einem Ärgernis und zu einer Vergeltung für sie!',
        10: 'Ihre Augen sollen verfinstert werden, damit sie nicht sehen, und ihren Rücken krümme fortwährend!“',
        11: 'Ich sage also: Sind sie etwa gestrauchelt, damit sie fallen? Keineswegs! Doch durch ihre Verfehlung [ist] den Nationen das Heil [entstanden], damit sie eifersüchtig werden.',
        12: 'Aber wenn ihre Verfehlung der Reichtum der Welt [ist] und ihr Fehler der Reichtum der Nationen, wie viel mehr ihre Fülle?!',
        13: 'Euch aber, den Nationen, sage ich: Insofern ich nun ein Apostel der Nationen bin, verherrliche ich meinen Dienst,',
        14: 'ob ich irgendwie mein Fleisch eifersüchtig machen und einige von ihnen retten kann.',
        15: 'Denn wenn ihre Verwerfung die Versöhnung der Welt [bedeutet], was [wird] dann ihre Annahme [bedeuten], wenn nicht Leben von den Toten?',
        16: 'Aber wenn der Erstling heilig [ist], dann auch der Teig; und wenn die Wurzel heilig [ist], dann auch die Zweige.',
        17: 'Wenn aber einige der Zweige abgebrochen worden sind und du, obwohl du ein wilder Ölbaum bist, unter ihnen eingepfropft und Mitteilhaber der Wurzel des Reichtums des Olivenbaums geworden bist,',
        18: 'dann brüstet euch nicht gegen die Zweige! Aber wenn du dich brüstet … nicht du trägst die Wurzel, sondern die Wurzel dich!',
        19: 'Du wirst nun sagen: „Zweige wurden abgebrochen, damit ich eingepfropft werde.“',
        20: 'Gut! Sie wurden durch Unglaube herausgebrochen, du aber stehst fest durch Glauben. Sei nicht überheblich, sondern fürchte dich!',
        21: 'Denn wenn Gott die natürlichen Zweige nicht verschont, dann wird er möglicherweise auch dich nicht verschonen.',
        22: 'Sieh also die Güte und Strenge Gottes: einerseits Strenge gegenüber denen, die gefallen sind, andererseits die Güte Gottes gegenüber dir – wenn du in der Güte bleibst, ansonsten wirst auch du abgeschnitten.',
        23: 'Aber auch jene werden eingepfropft werden, wenn sie nicht im Unglauben verharren – Gott ist nämlich fähig, sie wieder einzupfropfen.',
        24: 'Denn wenn du von dem von Natur aus wilden Olivenbaum abgeschnitten und entgegen der Natur in einen edlen Olivenbaum eingepfropft wurdest, wie viel mehr werden diese natürlichen [Zweige] dem eigenen Ölbaum eingepfropft werden.',
        25: 'Denn ich will euch über dieses Geheimnis nicht im Unklaren lassen, Geschwister, damit ihr nicht eingebildet seid: An Israel ist eine teilweise Verhärtung geschehen, bis die Fülle der [heidnischen] Völker eingegangen ist.',
        26: 'Und auf diese Weise wird ganz Israel gerettet werden, wie geschrieben steht: „Aus Zion wird der Retter kommen, er wird die Gottlosigkeiten von Jakob abwenden.',
        27: 'Und dies [ist] für sie der Bund von mir, sobald ich ihre Sünden fortnehme.“',
        28: 'Hinsichtlich der guten Nachricht [sind sie] zwar um euretwillen Feinde, aber hinsichtlich der Erwählung Geliebte um der Vorfahren willen;',
        29: 'denn die Gnadengaben und die Berufung Gottes [gelten] unwiderruflich.',
        30: 'Denn genau wie ihr Gott früher ungehorsam wart, aber jetzt infolge ihres Ungehorsam begnadigt worden seid,',
        31: 'so sind auch sie jetzt infolge eurer Begnadigung ungehorsam geworden, damit auch sie jetzt begnadigt werden.',
        32: 'Denn Gott hat sie alle in den Ungehorsam eingeschlossen, um sie alle zu begnadigen.',
        33: 'Oh Tiefe des Reichtums und der Weisheit und der Erkenntnis Gottes! Wie unerforschlich [sind] seine Urteile und unaufspürbar seine Wege!',
        34: 'Denn wer hat einen Gedanken des Herrn erkannt? Oder wer ist sein Berater gewesen?',
        35: 'Oder wer hat ihm vorher etwas gegeben, und es sollte ihm vergolten werden?',
        36: 'Denn aus ihm und durch ihn und zu ihm hin [sind] alle [Dinge]. Ihm [sei] die Herrlichkeit ‹für immer›! Amen.',
    },
    12: {
        1: 'Also ermahne ich euch, Geschwister, angesichts der Barmherzigkeit Gottes, eure Leiber als Opfer zur Verfügung zu stellen – lebendig, heilig, Gott wohlgefällig –, als euren vernünftigen Gottesdienst.',
        2: 'Und passt euch nicht diesem Zeitalter an, sondern lasst euch durch die Erneuerung des Verstandes umgestalten, damit ihr prüfen könnt, was der Wille Gottes [ist]: das Gute und Wohlgefällige und Vollkommene.',
        3: 'Denn durch die Gnade, die mir gegeben wurde, rate ich jedem, der unter euch ist, nicht höher [von sich] zu denken, als man denken sollte, sondern an das Bedachtsein zu denken, wie Gott einem jeden das Maß des Glaubens zugeteilt hat.',
        4: 'Denn wie wir an einem Körper viele Glieder haben und die vielen Glieder nicht dieselbe Aufgabe haben,',
        5: 'so sind wir – die vielen – ein einziger Leib in Christus, aber als Einzelne Glieder voneinander.',
        6: 'Und wir haben verschiedene Gnadengaben entsprechend der Gnade, die uns gegeben wurde: ob eine Weissagung, [dann geschehe es] nach der Übereinstimmung des Glaubens;',
        7: 'oder einen Dienst, [dann geschehe es] mit dem Dienst; oder wer lehrt, [der tue es] mit der Lehre;',
        8: 'oder wer ermutigt, [tue es] mit der Ermutigung; wer etwas beiträgt, [tue es] mit Aufrichtigkeit; wer vorsteht, [tue es] mit Eifer; wer Erbarmen hat, [tue es] mit Fröhlichkeit.',
        9: 'Die Liebe [sei] ungeheuchelt! Hasst das Böse; verpflichtet euch dem Gutem!',
        10: 'Mit geschwisterlicher Liebe [seid] freundlich zueinander, mit Ehrerbietung kommt einander zuvor,',
        11: '[seid] im Eifer nicht nachlässig, brennt im Geist, dient dem Herrn,',
        12: 'freut euch an der Hoffnung, haltet durch in der Bedrängnis, haltet fest am Gebet,',
        13: 'beteiligt euch an den Bedürfnissen der Heiligen, strebt nach der Gastfreundschaft!',
        14: 'Segnet diejenigen, die euch verfolgen – segnet, und flucht nicht!',
        15: 'Lacht mit den Lachenden, weint mit den Weinenden!',
        16: 'Bedenkt dasselbe miteinander! Bedenkt nicht die hohen [Dinge], sondern verbündet euch mit den Niedrigen. Werdet nicht eingebildet!',
        17: 'Vergeltet nichts Schlechtes mit Schlechtem! Seid auf das Gute bedacht vor den Augen aller Menschen!',
        18: 'Wenn es von euch aus möglich [ist], dann lebt mit allen Menschen in Frieden!',
        19: 'Rächt euch nicht selbst, geliebte [Geschwister], sondern gebt dem Zorn Raum, denn es steht geschrieben: „‚Mir [gehört] die Rache, ich werde vergelten‘, spricht der Herr.“',
        20: 'Sondern: „Wenn dein Feind Hunger hat, dann gib ihm zu essen; wenn er Durst hat, dann gib ihm zu trinken! Denn indem du dies tust, wirst du feurige Kohlen auf seinem Kopf häufen.“',
        21: 'Lass dich nicht vom Schlechten überwinden, sondern überwinde das Schlechte mit dem Guten!',
    },
    13: {
        1: 'Jede Menschenseele soll sich den regierenden Staatsmächten unterordnen. Es gibt nämlich keine Staatsmacht außer von Gott, und die bestehenden sind von Gott verordnet.',
        2: 'Wer sich der Staatsmacht widersetzt, der widersetzt sich somit Gottes Anordnung, und die sich widersetzen, werden für sich selbst ein Urteil erhalten.',
        3: 'Denn die Fürsten sind keine Abschreckung für das gute Werk, sondern für das schlechte. Du willst aber die Staatsmacht nicht fürchten!? Tue das Gute, dann wirst du von ihr gelobt werden.',
        4: 'Sie ist nämlich Gottes Dienerin, zu deinem Besten. Aber wenn du das Schlechte tust, dann fürchte dich! Sie trägt das Schwert nämlich nicht vergeblich, denn sie ist Gottes Dienerin, eine Rächerin zum Zorn für den, der das Schlechte tut.',
        5: 'Darum [ist es] notwendig, sich unterzuordnen – nicht allein wegen des Zornes, sondern auch wegen des Gewissens.',
        6: 'Deshalb entrichtet ihr nämlich auch Steuern; denn Diener Gottes sind genau dazu beschäftigt.',
        7: 'Zahlt allen [eure] Schulden: wem die Steuer [zusteht], die Steuer; wem der Zoll [zusteht], den Zoll; wem die Ehrfurcht [zusteht], die Ehrfurcht; wem die Ehre [zusteht], die Ehre.',
        8: 'Schuldet niemandem etwas, außer einander zu lieben! Denn wer den Anderen liebt, der hat das Gesetz erfüllt.',
        9: 'Denn das „Du sollst nicht ehebrechen! Du sollst nicht morden! Du sollst nicht stehlen! Du sollst nicht begehren!“(und wenn irgendein anderes Gebot [besteht]) wird in diesem Wort zusammengefasst, in dem: „Du sollst deinen Nächsten lieben wie dich selbst!“',
        10: 'Die Liebe bewirkt nichts Schlechtes für den Nächsten; die Erfüllung des Gesetzes [ist] also die Liebe.',
        11: 'Und dies [tut], weil ihr die Zeit kennt: dass die Stunde schon [da ist], dass ihr aus dem Schlaf aufwacht, denn jetzt [ist] unsere Rettung näher als [der Zeitpunkt], da wir zum Glauben gekommen sind.',
        12: 'Die Nacht ist fortgeschritten, und der Tag ist nahegekommen. Lasst uns also die Werke der Finsternis ablegen, und lasst uns die Waffen des Lichts anziehen.',
        13: 'Lasst uns wie bei Tage anständig leben – nicht in Fress- und Trinkorgien, nicht in Sexorgien und Ausschweifungen, nicht in Streit und Eifersucht –,',
        14: 'sondern zieht den Herrn Jesus Christus an und macht kein Aufheben um das Fleisch, sodass Begierden [entstehen].',
    },
    14: {
        1: 'Den Schwachen im Glauben aber nehmt an, nicht zur Unterscheidung der Überlegungen.',
        2: 'Der eine glaubt, [man könne] alles essen, der Schwache hingegen isst [nur] Gemüse.',
        3: 'Wer isst, soll den nicht verachten, der nicht isst, wer aber nicht isst, soll den nicht verurteilen, der isst, denn Gott hat ihn angenommen.',
        4: 'Wer bist du, der du einen fremden Hausdiener richtest? Dem eigenen Herrn steht oder fällt er. Er wird hingestellt aber werden, denn der Herr kann ihn hinstellen.',
        5: 'Der eine beurteilt nämlich ‹manchen Tag unterschiedlich›, der andere beurteilt jeden Tag [gleich]. Ein jeder soll in der eigenen Einsicht völlig überzeugt sein.',
        6: 'Wer den Tag achtet, der achtet ihn für den Herrn; Und wer isst, der isst für den Herrn, denn er dankt Gott; und wer nicht isst, der isst für den Herrn nicht, und er dankt Gott.',
        7: 'Denn keiner von uns lebt für sich selbst, und keiner stirbt für sich selbst.',
        8: 'Denn sowohl wenn wir leben, leben wir für den Herrn, als auch wenn wir sterben, sterben wir für den Herrn. Sowohl also wenn wir leben als auch wenn sterben, gehören wir dem Herrn.',
        9: 'Denn dazu ist Christus gestorben und lebendig geworden: damit er sowohl über die Toten als auch über die Lebenden herrscht.',
        10: 'Und warum richtest du deinen Bruder? Oder warum verachtest auch du deinen Bruder? Wir alle werden nämlich vor den Richterstuhl Gottes gestellt werden.',
        11: 'Denn es steht geschrieben: „Ich lebe, spricht der Herr, denn mir wird sich jedes Knie beugen, und jede Zunge wird Gott bekennen.“',
        12: 'Folglich wird nun ein jeder von uns Gott über sich selbst Rechtfertigung geben.',
        13: 'Lasst uns also nicht länger einander richten! Sondern entscheidet vielmehr Folgendes: dem Bruder nicht Anstoß oder Ärgernis zu geben.',
        14: 'Ich weiß und bin überzeugt im Herrn Jesus, dass nichts durch sich selbst unrein [ist] – außer für den, der meint, dass etwas unrein ist, für den [ist es] unrein.',
        15: 'Denn wenn dein Bruder wegen einer Speise betrübt wird, dann lebst du nicht länger gemäß der Liebe! Verdirb nicht mit deiner Speise jenen, für den Christus gestorben ist.',
        16: 'Euer Gutes soll also nicht in Verruf gebracht werden!',
        17: 'Das Reich Gottes ist nämlich nicht Essen und Trinken, sondern Gerechtigkeit und Frieden und Freude im heiligen Geist;',
        18: 'denn wer darin Christus dient, [findet] bei Gott Gefallen und bei den Menschen Anerkennung.',
        19: 'Folglich lasst uns also die [Dinge] des Friedens und der gegenseitigen Erbauung anstreben!',
        20: 'Zerstöre das Werk Gottes nicht wegen einer Speise! Zwar [ist] alles rein, doch [es ist] schlecht für den Menschen, der trotz Anstoß isst.',
        21: '[Es ist] gut, weder Fleisch zu essen noch Wein zu trinken noch etwas [zu tun], woran sich dein Bruder stößt.',
        22: 'Der Glaube, den du hast, habe für dich selbst vor Gott! Beglückwünschenswert [ist], wer sich selbst nicht mit dem richtet, was er bejaht.',
        23: 'Aber wer zweifelt, wenn er isst, der ist verurteilt, weil es nicht aus Glauben [geschieht]; und alles, was nicht aus Glauben [geschieht], ist Sünde.',
    },
    15: {
        1: 'Wir aber, die Starken, sind verpflichtet, die Schwachheiten der Kraftlosen zu tragen und nicht uns selbst zu gefallen.',
        2: 'Ein jeder von uns soll dem Nächsten gefallen zum Guten, zur Erbauung!',
        3: 'Denn auch Christus hat nicht sich selbst gefallen, sondern wie geschrieben steht: „Die Beschimpfungen derer, die dich beschimpfen, sind auf mich gefallen.“',
        4: 'Denn alles, was zuvor geschrieben wurde, wurde zu unserer Belehrung geschrieben, damit wir durch Geduld und durch die Ermutigung der Schrift Hoffnung haben.',
        5: 'Der Gott aber der Geduld und der Ermutigung möge es euch geben, untereinander dasselbe zu denken, gemäß Christus Jesus,',
        6: 'damit ihr einmütig mit einem Mund den Gott und Vater unseres Herrn Jesus Christus verherrlicht.',
        7: 'Darum nehmt einander an, wie auch Christus euch angenommen hat, zur Ehre Gottes.',
        8: 'Denn ich sage, dass Christus ein Diener der Beschneidung geworden ist um der Wahrheit Gottes willen, um die Verheißungen der Vorfahren zu bestätigen,',
        9: 'und damit die Nationen Gott für [sein] Erbarmen verherrlichen, wie geschrieben ist: „Deshalb werde ich dich unter den Nationen bekennen und deinem Namen lobsingen.“',
        10: 'Und außerdem heißt es: „Seid fröhlich, ihr Nationen, mit seinem Volk!“',
        11: 'Und außerdem: „Lobt den Herrn, all ihr Nationen, und alle Völker sollen ihn preisen!“',
        12: 'Und außerdem sagt Jesaja: „Die Wurzel Isaïs wird sein und derjenige, der sich erhebt, um die Nationen zu regieren; auf ihn werden die Nationen hoffen.“',
        13: 'Der Gott aber der Hoffnung möge euch erfüllen mit aller Freude und allem Frieden im Glauben, damit ihr überreich seid in der Hoffnung durch die Kraft des heiligen Geistes!',
        14: 'Und auch ich selbst, meine Geschwister, bin in Bezug auf euch überzeugt, dass auch ihr selbst voller Güte seid, erfüllt mit aller Erkenntnis, fähig, auch einander zu ermahnen.',
        15: 'Ich habe euch zum Teil nun kühn geschrieben, um euch zu erinnern um der Gnade willen, die mir von Gott verliehen wurde,',
        16: 'damit ich ein Diener Christi Jesu zu den Nationen sei, der priesterliche Aufgaben an der guten Nachricht Gottes verrichtet, sodass das Opfer der Nationen angenehm wird, geheiligt durch den heiligen Geist.',
        17: 'Ich habe also Grund zum Rühmen in Christus Jesus, ‹was das Verhältnis zu Gott betrifft›,',
        18: 'denn ich werde es nicht wagen, von etwas zu reden, das nicht Christus durch mich zum Gehorsam der Nationen mit Wort und Werk bewirkt hat,',
        19: 'in der Kraft der Zeichen und Wunder, in der Kraft des Geistes Gottes, sodass ich von Jerusalem und ringsum bis nach Illyrien die gute Nachricht von Christus erfüllt habe.',
        20: 'Aber so betrachte ich es als Privileg, die gute Nachricht zu verkünden, nicht wo Christus [bereits] benannt worden ist, damit ich nicht auf einem fremden Fundament baue,',
        21: 'sondern wie geschrieben steht: „Diejenigen, denen nicht über ihn verkündigt wurde, werden sehen, und diejenigen, die nicht gehört haben, werden verstehen.“',
        22: 'Darum war ich auch mehrmals daran gehindert, zu euch zu kommen;',
        23: 'jetzt aber, da ich in diesen Gegenden nicht länger einen Platz habe und seit vielen Jahren beabsichtige, zu euch zu kommen,',
        24: 'falls ich nach Spanien reise; denn ich hoffe, euch auf der Durchreise zu sehen und von euch dorthin auf die Reise geschickt zu werden, wenn ich zunächst [die Gemeinschaft mit] euch etwas genossen habe.',
        25: 'Jetzt aber reise ich nach Jerusalem, um den Heiligen zu dienen.',
        26: 'Denn es hat Makedonia und Achaja gefallen, einen gewissen Beitrag zu leisten für die Armen der Heiligen in Jerusalem.',
        27: 'Denn es hat ihnen gefallen, und sie sind ihre Schuldner. Denn wenn die Nationen an deren geistlichen [Segnungen] Anteil haben, sind sie verpflichtet, ihnen auch mit den irdischen [Segnungen] zu dienen.',
        28: 'Wenn ich dies also zu Ende gebracht und ihnen diese Frucht versiegelt habe, werde ich über euch nach Spanien reisen;',
        29: 'ich weiß aber, dass ich, wenn ich zu euch komme, in der Fülle des Segens von Christus kommen werde.',
        30: 'Ich ermahne euch aber, Geschwister, durch unseren Herrn Jesus Christus und durch die Liebe des Geistes, zusammen mit mir zu kämpfen in den Gebeten für mich zu Gott,',
        31: 'damit ich vor den Ungehorsamen in Judäa gerettet werde und mein Dienst für Jerusalem den Heiligen willkommen ist,',
        32: 'damit ich mit Freude zu euch komme durch den Willen Gottes und mich bei euch ausruhe.',
        33: 'Der Gott aber des Friedens [sei] mit euch allen, amen.',
    },
    16: {
        1: 'Nun empfehle ich euch Phöbe, unsere Schwester, die auch Dienerin der Gemeinde in Kenchreä ist,',
        2: 'damit ihr sie im Herrn empfangt, würdig der Heiligen, und ihr beisteht, mit welcher Tat auch immer sie euch braucht; denn auch sie ist vielen ein Beistand gewesen, auch mir selbst.',
        3: 'Grüßt Priska und Aquila, meine Mitarbeiter in Christus Jesus –',
        4: 'welche für mein Leben ihren eigenen Hals hingehalten haben und denen nicht nur ich danke, sondern auch alle Gemeinden der Nationen –',
        5: 'und die Gemeinde in ihrem Haus! Grüßt meinen geliebten Epänestos, der eine Erstlingsfrucht Asias für Christus ist.',
        6: 'Grüßt Maria, die sich viel um euch bemüht hat.',
        7: 'Grüßt Andronikus und Junia, meine Landsleute und meine Mitgefangenen, die wohl bekannt unter den Aposteln sind und die sogar vor mir in Christus gewesen sind.',
        8: 'Grüßt Ampliatus, meinen geliebten [Bruder] im Herrn.',
        9: 'Grüßt Urbanus, unseren Mitarbeiter in Christus, und meinen geliebten Stachys.',
        10: 'Grüßt Apelles, den bewährten [Bruder] in Christus! Grüßt die Hausgenossen von Aristobul!',
        11: 'Grüßt Herodion, meinen Landsmann. Grüßt die Hausgenossen von Narzissus, die im Herrn sind.',
        12: 'Grüßt Tryphäna und Tryphosa, die sich im Herrn mühen. Grüßt die geliebte Persis, die sich viel im Herrn bemüht hat.',
        13: 'Grüßt Rufus, den Erwählten im Herrn, und seine und meine Mutter.',
        14: 'Grüßt Asynkritus, Phlegon, Hermes, Patrobas, Hermas, und die Geschwister mit ihnen.',
        15: 'Grüßt Philologus und Julia, Nerëus und seine Schwester, und Olympas und alle Heiligen zusammen mit ihnen.',
        16: 'Grüßt einander mit dem heiligen Kuss! Es grüßen euch alle Gemeinden Christi.',
        17: 'Und ich ermahne euch, Geschwister, auf die zu achten, die entgegen der Lehre, die ihr gelernt habt, Spaltungen und Ärgernisse verursachen, und wendet euch von ihnen ab!',
        18: 'Denn solche [Leute] dienen nicht unserem Herrn Christus, sondern dem eigenen Bauch, und durch nette Worte und schöne Reden täuschen sie die Herzen der Arglosen.',
        19: 'Denn euer Gehorsam ist ‹allen zu Ohren› gekommen; ich freue mich also über euch, und ich will, dass ihr weise seid, ‹was das Gute anbelangt›, aber unverdorben, ‹was das Schlechte anbelangt›.',
        20: 'Der Gott aber des Friedens wird den Satan in Kürze unter euren Füßen zertrampeln. Die Gnade unseres Herrn Jesus [sei] mit euch!',
        21: 'Es grüßen euch Timotheus, mein Mitarbeiter, sowie Luzius und Jason und Sosipater, meine Landsleute.',
        22: 'Ich, Tertius, der ich diesen Brief geschrieben habe, grüße euch im Herrn.',
        23: 'Es grüßt euch Gajus, der mein und der ganzen Gemeinde Gastgeber [ist]. Es grüßen euch Erastus, der Verwalter der Stadt, und Bruder Quartus.',
        25: 'Dem aber, der euch gemäß meiner guten Nachricht und der Predigt von Jesus Christus stärken kann, gemäß der Offenbarung des Geheimnisses, das für ewige Zeiten geheim gehalten worden ist,',
        26: 'jetzt aber erschienen und durch die prophetischen Schriften auf Befehl des ewigen Gottes an alle Nationen bekannt gemacht worden ist, zum Gehorsam des Glaubens …',
        27: 'ihm, dem allein weisen Gott, durch Jesus Christus, [sei] die Ehre, ‹für immer›! Amen.',
    },
}
